Console.WriteLine(drink);

async Task<string> BrewAsync(string what)
{
    await Task.Delay(1000);          // stands in for a slow operation
    return $"Your {what} is ready";
}

using System.Diagnostics;

var clock = Stopwatch.StartNew();

string tea = await BoilAsync("tea", 2000);
string toast = await ToastAsync(1500);
Console.WriteLine($"Sequential: {tea}, {toast} in about {Math.Round(clock.Elapsed.TotalSeconds)} s");

clock.Restart();
Task<string> teaTask = BoilAsync("tea", 2000);      // starts immediately
Task<string> toastTask = ToastAsync(1500);          // starts immediately too
string[] results = await Task.WhenAll(teaTask, toastTask);
Console.WriteLine($"Concurrent: {string.Join(", ", results)} in about {Math.Round(clock.Elapsed.TotalSeconds)} s");

async Task<string> BoilAsync(string drink, int milliseconds)
{
    await Task.Delay(milliseconds);
    return $"{drink} done";
}

async Task<string> ToastAsync(int milliseconds)
{
    await Task.Delay(milliseconds);
    return "toast done";
}

using var http = new HttpClient();

HttpResponseMessage response = await http.GetAsync("https://example.com/");
Console.WriteLine((int)response.StatusCode);
Console.WriteLine(response.Content.Headers.ContentType?.MediaType);

string html = await response.Content.ReadAsStringAsync();
Console.WriteLine(html.Contains("<title>"));

using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(500));

try
{
    await DownloadAsync(cts.Token);
    Console.WriteLine("Finished");
}
catch (OperationCanceledException)
{
    Console.WriteLine("Cancelled after 500 ms");
}

async Task DownloadAsync(CancellationToken token)
{
    for (int chunk = 1; chunk <= 5; chunk++)
    {
        await Task.Delay(200, token);
        Console.WriteLine($"chunk {chunk}");
    }
}
